-- 1. Enable PostGIS
CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE drivers (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100),
    current_location GEOGRAPHY(POINT, 4326) -- Standard GPS WGS 84
);

CREATE INDEX idx_drivers_location ON drivers USING gist (current_location);

-- 2. Find drivers within 5,000 meters of customer GPS point
SELECT id, name, ST_Distance(current_location, ST_MakePoint(-73.9851, 40.7488)::geography) AS distance_meters
FROM drivers
WHERE ST_DWithin(current_location, ST_MakePoint(-73.9851, 40.7488)::geography, 5000)
ORDER BY distance_meters ASC
LIMIT 10;
